 # Dropdown indicators share the registry's stroke, shape and neutral palette.
 svg=icon('chevronDown').replace('currentColor','#7B8188')
 css+=':is(#app,#dialog,.ds-preview) select{appearance:none;padding-right:44px;background-image:url("data:image/svg+xml,'+quote(svg,safe='')+'");background-repeat:no-repeat;background-position:right 14px center;background-size:20px;}\n'
 css+=':is(#app,#dialog,.ds-preview) .rt-field input{background-image:none;padding-left:0;}\n'
